#include <vector>
#include <algorithm>

using namespace std;

long long n, k;

int main() {
    cin >> n >> k;

    vector<long long> l(n), l1(n, 0);  // l1 initialized directly with 0

    for (int i = 0; i < n; i++) {
        cin >> l[i];
    }

    for (int i = 1; i < n; i++) {
        long long diff = l[i] - l[i - 1];  // Calculate the difference once
        l1[i] = l1[i - 1] + (diff < 0 ? -diff : diff);  // Use the pre-calculated difference for abs

        for (int j = 1; j <= min(i * 1ll, k); j++) {
            l1[i] = min(l1[i], l1[i - j] + (l[i - j] - l[i] < 0 ? -(l[i - j] - l[i]) : (l[i - j] - l[i])));  // Reuse the calculation
        }
    }

    cout << max(0 * 1ll, l1[n - 1]) << endl;
}

